import { describe, it } from "vitest";
// Implementation under test (to be created in the Green phase):
// import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office - quote", () => {
  it.todo("should return a premium of 5 G for a quote with an empty item list");
  it.todo("should return a premium of 115 G for a single plain sword (100 base + 10 first insurance + 5 fee)");
  it.todo("should use the price list base premium for amulet, staff and potion");
  it.todo("should sum the base premiums of several main items in one quote");
  it.todo("should charge 25 G base premium per component (2 runes -> 50 G base)");
  it.todo("should charge 60 G base premium for a block of exactly 3 alike components (3 runes)");
  it.todo("should not apply the block discount for 4 runes (100 G base premium)");
  it.todo("should apply one block plus singles for 7 runes (175 G base premium)");
  it.todo("should not form a block from different component types (2 runes + 1 moonstone -> 75 G base)");
  it.todo("should form two separate blocks for 3 runes + 3 moonstones (120 G base premium)");
  it.todo("should add a 50 % curse surcharge on the base premium of the cursed item");
  it.todo("should apply the curse surcharge only to the cursed item in a multi-item policy (cursed sword + plain amulet -> 210 G before policy modifiers and fee)");
  it.todo("should add a 30 % high-enchantment surcharge for an item with enchantment exactly 5");
  it.todo("should not add the high-enchantment surcharge for an item with enchantment 4");
  it.todo("should apply both curse and high-enchantment surcharges to the same item");
  it.todo("should apply a 20 % loyalty discount on the policy base premium for a customer with exactly 2 years with MHPCO");
  it.todo("should not apply the loyalty discount for a customer with 1 year with MHPCO");
  it.todo("should apply the 10 % first insurance surcharge on the policy base premium of every quote");
  it.todo("should apply a 15 % follow-up discount on the policy base premium for each quote after the customer's first");
  it.todo("should add the 5 G processing fee at the very end, after all discounts and surcharges");
  it.todo("should round the final premium up (197.5 G -> 198 G) while keeping intermediate values as fractions");
  it.todo("should return 165 G for a newcomer with a cursed steel sword of enchantment 3");
  it.todo("should return 160 G for a 3-year customer's second quote with a cursed steel sword of enchantment 7");
});

describe("MHPCO Claim Office - claim", () => {
  it.todo("should subtract the 100 G deductible from the damage amount (sword, 500 G damage -> 400 G payout)");
  it.todo("should reimburse a component minus the deductible (rune, 200 G damage -> 100 G payout)");
  it.todo("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G -> 600 G payout)");
  it.todo("should reimburse 50 % before the deductible for an item with enchantment exactly 8 (1000 G damage -> 400 G payout)");
  it.todo("should reimburse 50 % before the deductible for an item with enchantment 9 (steel sword, 1000 G damage -> 400 G payout)");
  it.todo("should fully reimburse dragon-material items before the deductible (dragon sword enchantment 5, 800 G damage -> 700 G payout)");
  it.todo("should let the 50 % high-enchantment rule win over dragon material (dragon sword enchantment 9, 1000 G damage -> 400 G payout)");
  it.todo("should treat two damage entries of the same insured item type as separate damages with their own deductible");
  it.todo("should report the remaining cap of twice the insurance sum after a claim");
  it.todo("should base the cap on the unmodified insurance values, not on the premium (cursed sword -> cap 2000 G)");
  it.todo("should base the cap on the unmodified insurance values of components, not on the block discount (sword + 3 runes -> insurance sum 1750 G)");
  it.todo("should cap the cumulative payout across successive claims (1500 G then 1500 G on a sword -> 1400 G then 600 G, remaining cap 0 G)");
  it.todo("should round the final payout down (350.5 G -> 350 G)");
});

describe("MHPCO Claim Office - rejected scenarios", () => {
  it.todo("should reject a quote containing an item with an unknown type");
  it.todo("should reject a claim whose damage entry references an item type not covered by the policy");
  it.todo("should reject a claim whose damage entry references an unknown item type");
  it.todo("should reject a claim with more damage entries of a type than the policy insures");
  it.todo("should reject a claim with a negative damage amount");
});

import { describe, it } from "vitest";
// CLI under test (to be created in the Green phase): src/cli.ts,
// executed as a child process with JSON on stdin.

describe("claim-office CLI", () => {
  it.todo("should read a scenario from stdin and write {results:[{premium}]} to stdout for a single quote step");
  it.todo("should write one result per step, in the same order as the input steps");
  it.todo("should write {payout, remainingCap} for a claim step referring to an earlier quote step by index");
  it.todo("should exit with status 0 for a valid scenario");
  it.todo("should exit non-zero and write an error description to stderr, with no results on stdout, for a quote with an unknown item type");
  it.todo("should exit non-zero and write an error description to stderr for a claim with a negative damage amount");
});
